INSERT INTO keywords (name, description) VALUES ("ABDUCCIÓN", "Del lat .abductio,-onis, separación.in., abduction. Acto de separar una parte del eje del cuerpo; acto de volver hacia fuera.Movimiento que se aleja de la linea media.");
INSERT INTO keywords (name, description) VALUES ("ACINESIA", "De a- y de gr .Kinesis,movimiento.in., akinesia .Falta pérdida o cesación de movimiento.");
INSERT INTO keywords (name, description) VALUES ("ADUCCIÓN", "Del lat.adductio,-onis. in adduction. Acto de acercar un miembro u otro órgano al plano medio; contrario a la abducción. Movimiento en dirección a la línea media.");
INSERT INTO keywords (name, description) VALUES ("AFASIA", "Pérdida del uso o comprensión de la palabra.");
INSERT INTO keywords (name, description) VALUES ("AGONISTAS", "Músculos o porciones de estos, insertados anatómicamente de forma que cuando se contraen desarrollan fuerzas que se complementan o refuerzan mutuamente.");
INSERT INTO keywords (name, description) VALUES ("ÁLGERA", "Parálisis o supresión voluntaria del movimiento, producida por un intenso dolor que ocasionan los movimientos voluntarios. Se observa a menudo en estados histéricos.");
INSERT INTO keywords (name, description) VALUES ("ÁLGIAS VERTEBRALES O RAQUIALGIAS", "Dolor vertebral inespecífico, y localizado en cualquier zona del raquis, sin un diagnóstico establecido.");
INSERT INTO keywords (name, description) VALUES ("ALZHEIMER, ENFERMEDAD DE", "In., Alzheimer's disease .Demencia presenil caracterizada por confusión, trastornos de la memoria , desorientación, intranquilidad, agnosia, trastornos del lenguaje, incapacidad para llevar a cabo movimientos intencionados, alucinaciones. La enfermedad suele comenzar al final de las edades medias de la vida con pequeños defectos de memoria y de conducta ,y afecta con igual frecuencia a hombres que a mujeres.");
INSERT INTO keywords (name, description) VALUES ("AMASAMIENTO", "Una de las maniobras básicas del masaje. Consiste en coger, deslizar y levantar el tejido, intentando despegarlo del plano profundo y buscando desplazarlo transversalmente de un lado a otro, realizando al mismo tiempo una presión y un estiramiento con una ligera torsión del mismo.");
INSERT INTO keywords (name, description) VALUES ("ANCLAJE", "Parte del vendaje cuya función es la de preparar una superficie idónea para adherir a ella las tiras activas.");
INSERT INTO keywords (name, description) VALUES ("ANQUILOSIS", "Imposibilidad de movimiento en una articulación normalmente móvil, a consecuencia de una soldadura anormal de las superficies articulares o de producciones óseas extraarticulares.");
INSERT INTO keywords (name, description) VALUES ("APLICAR", "Etapa del método de intervención en fisioterapia que consiste en llevar a cabo el plan de actuación fisioterápica que previamente se ha formulado.");
INSERT INTO keywords (name, description) VALUES ("APOPLEJÍA", "Del gr apoplesso , enajenar. Incapacidad funcional que se presenta bruscamente en forma de ataque, en órganos esenciales, especialmente en el cerebro ( por hemorragia cerebral, obturación de vasos).");
INSERT INTO keywords (name, description) VALUES ("APRAXIA", "Trastorno de la actividad voluntaria que consiste en la imposibilidad de realizar movimientos dirigidos a un fin, a pesar de poder realizar los movimientos elementales.");
INSERT INTO keywords (name, description) VALUES ("ARCO DOLOROSO", "Es el dolor que aparece a mitad de camino en la amplitud articular activa y pasiva, de modo que antes y después no hay dolor. Indica que una estructura sensible queda atrapada a presión entre dos superficies óseas.");
INSERT INTO keywords (name, description) VALUES ("ARCO REFLEJO", "In., reflex arc. Unidad neurológica sencilla de una neurona sensitiva que transmite un impulso a la médula espinal, donde conecta con una neurona motora que trasmite el impulso reflejo de vuelta a un músculo.");
INSERT INTO keywords (name, description) VALUES ("ARTICULACIÓN COMPUESTA", "In., compound joint. Cualquier articulación formada por más de dos huesos.");
INSERT INTO keywords (name, description) VALUES ("ARTRITIS REUMATOIDE", "También llamada poliartritis crónica progresiva.Proceso reumático, crónico, inflamatorio y evolutivo que se lleva a la impotencia funcional absoluta de las articulaciones. Se trata de una artropatía inflamatoria de origen desconocido y que aparece sobre todo en mujeres, y con una afectación en general distal y simétrica. Se distinguen brotes inflamatorios y periodos entre brotes.");
INSERT INTO keywords (name, description) VALUES ("ARTROSIS", "También llamada osteoartritis u osteoartrosis. Trastorno caracterizado por el deterioro o pérdida progresiva de cartílago articular que viene acompañado de proliferación del tejido óseo nuevo y tejido blando en la articulación afectada y en las zonas periarticulares. Afecta de manera especial a las articulaciones que soportan peso o que se utilizan mas frecuentemente .Según su ubicación recibe nombres concretos Ej gonartrosis (en la rodilla).");
INSERT INTO keywords (name, description) VALUES ("ATROFIA", "Disminución del volumen o de la función de un órgano o tejido.");
INSERT INTO keywords (name, description) VALUES ("ATROFIA MUSCULAR", "Disminución del volumen y peso de un músculo por defecto de nutrición.");
INSERT INTO keywords (name, description) VALUES ("ABDUCCIÓN", "Del lat .abductio,-onis, separación.in., abduction. Acto de separar una parte del eje del cuerpo; acto de volver hacia fuera.Movimiento que se aleja de la linea media.");
INSERT INTO keywords (name, description) VALUES ("ACINESIA", "De a- y de gr .Kinesis,movimiento.in., akinesia .Falta pérdida o cesación de movimiento.");
INSERT INTO keywords (name, description) VALUES ("ADUCCIÓN", "Del lat.adductio,-onis. in adduction. Acto de acercar un miembro u otro órgano al plano medio; contrario a la abducción. Movimiento en dirección a la línea media.");
INSERT INTO keywords (name, description) VALUES ("AFASIA", "Pérdida del uso o comprensión de la palabra.");
INSERT INTO keywords (name, description) VALUES ("AGONISTAS", "Músculos o porciones de estos, insertados anatómicamente de forma que cuando se contraen desarrollan fuerzas que se complementan o refuerzan mutuamente.");
INSERT INTO keywords (name, description) VALUES ("ÁLGERA", "Parálisis o supresión voluntaria del movimiento, producida por un intenso dolor que ocasionan los movimientos voluntarios. Se observa a menudo en estados histéricos.");
INSERT INTO keywords (name, description) VALUES ("ÁLGIAS VERTEBRALES O RAQUIALGIAS", "Dolor vertebral inespecífico, y localizado en cualquier zona del raquis, sin un diagnóstico establecido.");
