INSERT INTO keywords (name, description) VALUES ("ARTROSIS", "También llamada osteoartritis u osteoartrosis. Trastorno caracterizado por el deterioro o pérdida progresiva de cartílago articular que viene acompañado de proliferación del tejido óseo nuevo y tejido blando en la articulación afectada y en las zonas periarticulares. Afecta de manera especial a las articulaciones que soportan peso o que se utilizan mas frecuentemente .Según su ubicación recibe nombres concretos Ej gonartrosis (en la rodilla).");
INSERT INTO keywords (name, description) VALUES ("ATROFIA", "Disminución del volumen o de la función de un órgano o tejido.");
INSERT INTO keywords (name, description) VALUES ("ATROFIA MUSCULAR", "Disminución del volumen y peso de un músculo por defecto de nutrición.");
INSERT INTO keywords (name, description) VALUES ("BIOFEEDBACK", "Retroalimentación de la actividad de procesos fisiológicos, en forma de señales de naturaleza òptica, acùstica o de otro genero, con el fin de posibilitar la propia dirección consciente de procesos corporales y anímicos aparentemente autónomos.");
INSERT INTO keywords (name, description) VALUES ("BOBATH O NDT, TÉCNICA DE", "In. Neurodevelopmental treatment.Técnica empleada por la Sra Bobath y su esposo el Dr, K. Bobath, inhibiendo los esquemas de movimiento patológico, e influyendo en el tema muscular.");
INSERT INTO keywords (name, description) VALUES ("BRADICARDIA", "Del gr Bradys , lento y Cardia , Corazón ; lentitud anormal del pulso");
INSERT INTO keywords (name, description) VALUES ("BRADICINESIA", "Del gr Bradys , lento y Kinesis , moviviento; lentitud anormal del movimiento.");
INSERT INTO keywords (name, description) VALUES ("BURSITIS", "Inflamación o irritación de una bursa o bolsa serosa que es una pequeña bolsa situada entre el hueso y otras estructuras móviles como músculos, la piel o los tendones y facilita un movimiento suave de estas estructuras.");
INSERT INTO keywords (name, description) VALUES ("CELULITIS", "Sobrecarga de grasa localizada, debido de una hipertrofia de las células grasas de la hipodermis, acompañada de un problema vascular como es la retención de líquidos y una desorganización de tejido conjuntivo.");
INSERT INTO keywords (name, description) VALUES ("CIÁTICA", "Inflamación dolorosa del nervio ciático, caracterizada por parestesia del muslo y pierna, sensibilidad en el trayecto del nervio y algunas veces atrofia muscular; Ciatalgia.");
INSERT INTO keywords (name, description) VALUES ("CINESITERAPIA", "Del gr Kinesis , movimiento, y Therapeya, tratamiento.In. Kinesiotherapy. Tratamiento por medio del movimiento.");
INSERT INTO keywords (name, description) VALUES ("CONDROMALACIA", "Reblandecimiento anormal de los cartílagos.");
INSERT INTO keywords (name, description) VALUES ("CONTRACCIÓN", "Del lat contractio,-onis. In. Contraction; manifestación de contractilidad; acortamiento de un músculo en respuesta normal a un estimulo nervioso.");
INSERT INTO keywords (name, description) VALUES ("CONTRACTURA", "Del lat contractura. In. , contracture. Contracción involuntaria duradera o permanente, de uno o mas grupos musculares, que mantiene la parte respectiva en posición viciosa, difícil o imposible de corregir por movimientos pasivos. Puede aparecer acompañando roturas musculares.");
INSERT INTO keywords (name, description) VALUES ("CONTRAER/RELAJAR", "Técnica de relajación que consite en la contracción potente del grupo muscular al que se desea relajar.El fisioterapeuta coloca la articulación que hay que movilizar en la máxima amplitud posible y pide al individuo una contracción fuerte del músculo que desea relajar.Aguanta la contracción sin permitir movimiento durante seis segundos y a continuación solicita la relajación total, de manera que se moviliza conseguir mayor amplitud. Sus efectos son la mejora de la movilidad de articulaciones rigidas , disminución de la contratura muscular periferica dolorosa y relajación de la musculatura.");
INSERT INTO keywords (name, description) VALUES ("COORDINACIÓN", "Del lat cordinatio-onis. In., coordination.Actividad armonica de partes que cooperan en una función, como la cooperación de grupos musculares bajo la dirección cerebral.");
INSERT INTO keywords (name, description) VALUES ("CORRIENTE ALTERNA", "El movimiento de los electrones se hace alternativamente en ambos sentidos.");
INSERT INTO keywords (name, description) VALUES ("CORRIENTE BIDIRECIONAL", "Cuando el desplazamiento iónico sucede en ambos sentidos.");
INSERT INTO keywords (name, description) VALUES ("CORRIENTE CONTINUA", "Cuando la diferencia de potencial entre los bornes es constante y siempre uno de ellos esta a mayor potencia que el otro, siendo uno el positivo y el otro el negativo.");
INSERT INTO keywords (name, description) VALUES ("CRIOTERAPIA", "In,.Cryotherapy tratamiento de algunas afecciones por el empleo del frío.");
INSERT INTO keywords (name, description) VALUES ("CRÓNICO", "De larga duración semanas, meses , años pero no necesariamente irreversible. Los síntomas pueden ser moderados o severos.");
INSERT INTO keywords (name, description) VALUES ("CYIRIAX", "Masaje de fricción transversal profunda.");
INSERT INTO keywords (name, description) VALUES ("DECUBITO", "Del lat decubitus, p.p. decumbere, acostarse . In decubitus. Actitud del cuerpo en estado de reposo sobre un plano mas o menos horizontal.");
INSERT INTO keywords (name, description) VALUES ("DEFICIENCIA", "Perdida o anormalidad de una estructura o funcion psicológica o anatómica. Representa la esteriorización de un estado patológico y refleja la perturbación a nivel de un órgano.");
INSERT INTO keywords (name, description) VALUES ("DERRAME", "Acumulación anormal de líquidos o gases en una cavidad natural o accidental.");
INSERT INTO keywords (name, description) VALUES ("DESEQUILIBRIO MUSCULAR", "Estado en el que un músculo esta debilitado, mientras que sus antagonistas no lo están.");
INSERT INTO keywords (name, description) VALUES ("DESGARRO MUSCULAR", "Solución de continuidad del tejido muscular de bordes desiguales y franjeados , producida por un estiramiento o avulsión.");
INSERT INTO keywords (name, description) VALUES ("DIAFRAGMA", "Tabique musculomembranoso que separa el tórax del abdomen. Músculo importante en la respiración.");
INSERT INTO keywords (name, description) VALUES ("DIGITOPRESION", "Del lat digitus, dedo y pressio-onis, apretar, comprimir. Presión con el dedo o masaje manual sobre puntos basadas en las técnicas japonesas del shiatsu.");
INSERT INTO keywords (name, description) VALUES ("DIGITOPUNTURA", "Del lat digitus, dedo y Punctura, punción . Presión con el dedo sobre puntos basados en las técnicas chinas de acupuntura.");
INSERT INTO keywords (name, description) VALUES ("DISCAPACIDAD", "Es toda restricción o ausencia (debido a una deficiencia) de la capacidad de realizar una actividad en la forma o el margen que se considera normal para un ser humano.");
INSERT INTO keywords (name, description) VALUES ("DISCAPACITADO", "In., disable. Dicho de una persona que tiene impedida o entorpecida alguna de las actividades cotidianas consideradas normales, por alteración de sus funciones intelectuales o físicas.");
INSERT INTO keywords (name, description) VALUES ("DISFUNCIÓN", "Desarreglo en el funcionamiento de algo o en la función que le corresponde.");
INSERT INTO keywords (name, description) VALUES ("DISINERGIA", "Disociación de los músculos que deben llevar a cabo una función.");
INSERT INTO keywords (name, description) VALUES ("DISNEA", "Trastorno respiratorio que se manifiesta por modificaciones del ritmo amplitud o frecuencia de los movimientos de la respiración. Es un signo de insuficiencia respiratoria.");
INSERT INTO keywords (name, description) VALUES ("DISTENDER", "Aflojar , relajar , disminuir la tensión.");
INSERT INTO keywords (name, description) VALUES ("DOLOR", "Del lat. Dolor. In. Pain. Impresión penosa experimentada por un organo o parte y transmitida al cerebro por los nervios sensitivos.");
INSERT INTO keywords (name, description) VALUES ("DOLOR REFERIDO (DE UN PUNTO GATILLO)", "Dolor originado en un punto gatillo, pero que se siente a distancia, a menudo muy alejado de su fuente. El patrón de dolor referido es reproducible en relación con su lugar de origen.");
INSERT INTO keywords (name, description) VALUES ("DRENAJE", "Derivación temporal o definitiva de una secreción, normal o patológica, hacia el exterior o hacia un órgano interno.-Linfatico manual. Técnica masoterápica para el tratamiento de linfedemas.");
INSERT INTO keywords (name, description) VALUES ("EDEMA", "Acumulación de liquido seroalbuminoso en el tejido celular como consecuencia de alguna de las siguientes situaciones: disminución de la presión osmótica del plasma por reducción de las proteínas, aumento de la presión hidrostática de los capilares por insuficiencia cardiaca; mayor permeabilidad de las paredes capilares u obstrucción de las vías linfáticas.");
INSERT INTO keywords (name, description) VALUES ("ELASTICIDAD", "Habilidad de un material de resistir la deformación por parte de una fuerza externa y la capacidad de volver a su longitud original cuando desaparece la fuerza externa. Cualidad reológica de las secreciones bronquiales.");
INSERT INTO keywords (name, description) VALUES ("ELECTRODIAGNÓSTICO", "La implantación de una aguja uni o bipolar en el músculo hace que su actividad sea detectada en un osciloscopio.");
INSERT INTO keywords (name, description) VALUES ("ELECTROESTIMULACIÓN", "Técnica que utiliza la corriente eléctrica (Habitualmente la exponencial) para provocar un estimulo sobre el músculo denervado.");
INSERT INTO keywords (name, description) VALUES ("ELECTROMUSCULACIÓN", "Técnica fisioterápica (Habitualmente con corrientes farádicas) Cuyo objetivo es el reforzamiento muscular en las atrofias de músculos inervados.");
INSERT INTO keywords (name, description) VALUES ("ELECTROTERAPIA", "In., Electrotherapy. Utilización terapéutica de las corrientes eléctricas.");
INSERT INTO keywords (name, description) VALUES ("ENLONGACIÓN", "Del lat .Enlongatio,-onis . In., elongation. Extensión , estiramiento ,distensión.");
INSERT INTO keywords (name, description) VALUES ("EMBOLIA GRASA", "Complicación de las Fracturas. Consiste en una insuficiencia respiratoria aguda debida al paso de gotas de grasa desde la zona de la fractura a la circulación pulmonar y cerebral.");
INSERT INTO keywords (name, description) VALUES ("EPICONDILITIS", "Inflamación del tendón común de inserción de los músculos extensores de muñeca y dedos. Tambien conocido como CODO DE TENSITA. Se produce por una sobrecarga repetida.");
INSERT INTO keywords (name, description) VALUES ("ESCLEROSIS MÚLTIPLE", "(EM). In Múltiple Sclerosis (MS). Enfermedad progresiva caracterizada por la desmielinización diseminada de las fibras nerviosas del cerebro y de la médula espinal. Los primeros signos son parestesias o sensaciones anormales en las extremidades o en un lado de la cara. Otros signos precoces son la perdida de masa muscular, el vertigo y las alteraciones visuales, como visión doble y ceguera parcial. Después en el curso de la enfermedad puede existir labilidad emocional, ataxia, reflejos anormales y dificultad para orinar.");
INSERT INTO keywords (name, description) VALUES ("ESCOLIOSIS", "Desviación lateral de la columna vertebral.");
INSERT INTO keywords (name, description) VALUES ("ESGUINCE", "Conjunto de lesiones capsulares y ligamentosas producidas por un mecanismo agudo que sobrepasa el limite funcional, pero sin que llegue a alterar la congruencia articular . Cuando se altera la congruencia articular setrata de una luxación. La gravedad o grado del esguince depende del grado de rotura o no del ligamento y va desde la distensión al grado I,II y III.");
INSERT INTO keywords (name, description) VALUES ("ESPASMO", "Aumento de la tensión de un músculo, con o sin su acortamiento debido a actividad involuntaria de la motoneurona. El espasmo se identifica por potenciales de la unidad motora que no pueden ser interrumpidos por la relajación voluntaria. Debe distinguirse de la contractura.");
INSERT INTO keywords (name, description) VALUES ("ESPASTICIDAD", "Aumento patológico y mantenido del tono muscular, de carácter generalizado cuyo origen es una lesión de origen central.");
INSERT INTO keywords (name, description) VALUES ("ESPONDILÓLISIS", "Disolución o destrucción de una vértebra.");
INSERT INTO keywords (name, description) VALUES ("ESTIRAMIENTO", "Cualquier procedimiento que enlongue las fibras musculares.");
INSERT INTO keywords (name, description) VALUES ("EVERSIÓN", "Movimiento combinado de flexión dorsal, abdución y pronación ,alrededor del eje de Hencke.");
INSERT INTO keywords (name, description) VALUES ("FACILITACION NEUROMUSCULAR PROPIOCEPTIVA (FNP)", "También llamado método KABAT. Ley de Sherrington de inervación reciproca y de inducción sucesiva, irradiación o reforzamiento . El método se define como la utilización de informaciones de origen superficial (Táctil) y de origen profundo (Posición articular, estiramiento de tendones y músculos) para producir una excitación del sistema nervioso que a su vez hace funcionar la musculatura. Se utilizan unos patrones funcionales facilitadores de movimiento en diagonal que mejoran el esquema motor y se basan en cuatro principios neurológicos: facilitacion e inhibición, irradiación o reforzamiento , ley de Sherrinton de inducción sucesiva y ley de Sherrinton de inervación reciproca.");
INSERT INTO keywords (name, description) VALUES ("GALVANIZACIÓN", "Aplicación de la corriente galvánica al diagnostico y tratamiento.");
INSERT INTO keywords (name, description) VALUES ("GIMNASIA", "Del lat.gimnasia y éste del gr.gimnasia,ejercicio,de gymnos, desnudo.in,gymnastics. Ejercicio muscular sistematico,general o parcial.-Terapeutica. Ejercicio que se realiza con un fin terapéutico.");
INSERT INTO keywords (name, description) VALUES ("GOTA", "Artritis inducida por acumulación de cristales en la cavidad articular.Es más frecuente en hombres que en mujeres,y se asocia a excesos de comida y bebida. Se desarrolla en episodios de artritis aguda y a medida que avanza la enfermedad pasa a ser artritis crónica con lesiones de tejidos blandos y riñón.");
INSERT INTO keywords (name, description) VALUES ("HELIOTERAPIA", "De helio y therapeia, tratamiento.In.,heliot-herapy.Tratamiento por medio de la exposición del cuerpo o de una parte de los rayos solares.Tambien llamada cura o baños de sol.");
INSERT INTO keywords (name, description) VALUES ("HIDROCINESITERAPIA", "Conjunto de aplicaciones hidroterapicas que emplean el movimiento en el medio acuatico para el tratamiento de patologías.");
INSERT INTO keywords (name, description) VALUES ("HIDROTERAPIA", "In.,Hydrotherapy.Empleo del agua en el tratamiento de las enfermedades, especialmente en forma de abluciones,baños y duchas.");
INSERT INTO keywords (name, description) VALUES ("HIDROTERMAL", "Perteneciente o relativo a las aguas minerales cálidas.");
INSERT INTO keywords (name, description) VALUES ("HIPERLORDOSIS", "Curva anormal de convexidad anterior de la columna en el plano sagital. -cervical.Aumento de la lordosis fisiológica con desplazamiento anterior de la cabeza con respecto al eje vertí coaxial.-lumbar.Aumento de la lordosis fisiológica con desplazamiento anterior de la columna lumbar con respecto al eje.");
INSERT INTO keywords (name, description) VALUES ("HIPERTONIA", "De hiper y el gr.tonos,tensión.In., hypertonia.Tono o tensión exagerados, especialmente el tono muscular;de las diversas variedades de hipertonia muscular son dos las mas importantes: la espasticidad, que es debida a las lesiones piramidales,y la rigidez,que se debe a lesiones extrapiramidales.");
INSERT INTO keywords (name, description) VALUES ("HIPERTROFIA", "Aumento del tamaño de los organos debido a un aumento de volumen de las celulas y de la sustancia intercelular.");
INSERT INTO keywords (name, description) VALUES ("INERVACIÓN", "Del lat.in,en,y nervus,nervio.In.,innervation.Conjunto de las acciones nerviosas. Distribución de nervios o de energia nerviosa en una parte,organo o región.-reciproca.inervación de los músculos en la que los centros motores se hallan conectados de tal suerte que,cuando son excitados los agonistas,los antagonistas son inhibidos.");
INSERT INTO keywords (name, description) VALUES ("INMOVILIZACIÓN", "De in- y el lat. movilis, movible. In., inmobilizatión.Supresión de la movilidad articular.-absoluta. Aquella que impide totalmente el movimiento.-relativa.Aquella que impide solamente los grados de movimiento lesivo.");
INSERT INTO keywords (name, description) VALUES ("INTRUSISMO", "De Intruso. Ejercicio de actividades profesionales por persona no autorizada para ello. Puede constituir delito.");
INSERT INTO keywords (name, description) VALUES ("IONTOFORESIS", "In.,Iontophoresis.Tambien llamada electroforesis consiste en el aprovechamiento de la corriente galvánica o continua para introducir medicamentos en el interior del organismo.");
INSERT INTO keywords (name, description) VALUES ("ISQUEMIA", "Del gr.ischein, retener ,y haima, sangre.In.,ischemia.Detención de la circulación arterial en una parte y estado consecutivo de la misma.");
INSERT INTO keywords (name, description) VALUES ("JAULA DE ROCHER", "Elemento metálico con forma cúbica compuesto por cuatro planos enrejados.Utilizado para realizar montajes de poleoterapia y suspensoterapia.");
INSERT INTO keywords (name, description) VALUES ("KABAT, metodo de", "(ver FACILITACION NEUROMUSCULAR PROPIOCEPTIVA (FNP)");
INSERT INTO keywords (name, description) VALUES ("LAXITUD", "In lax.Proceso de relajación o aflojamiento.");
INSERT INTO keywords (name, description) VALUES ("LESIÓN", "Del lat.laesio,-onis.In., Lesion.Daño o alteracion morbosa organica o funcional, de los tejidos corporales.");
INSERT INTO keywords (name, description) VALUES ("LINFEDEMA", "De linfa y edema. in., lymphedema.Edema por obstrucción de un vaso linfático. Acumulación de un liquido en el espacio intesticial ocasionado por una alteración en la circulación linfática.");
INSERT INTO keywords (name, description) VALUES ("LUMBALGIA", "Dolor en las regiones lumbar,sacra y/o glútea;termino descriptivo que no identifica un diagnóstico o causa.");
INSERT INTO keywords (name, description) VALUES ("LUXACIÓN", "Conjunto de lesiones capsulares y ligamentosas consecuencia de un mecanismo de lesión que vence la resistencia elástica de estas estructuras, y por su gravedad conducen al fracaso de la estabilidad cápsulo-ligamentosa y conlleva la pérdida de la congruencia normal articular.La luxación puede ser parcial o completa dependiendo de la extensión de la perdida de contacto entre las superficies articulares.");
INSERT INTO keywords (name, description) VALUES ("MAGNETOTERAPIA", "Técnica terapéutica que consiste en aplicar campos magnéticos artificiales a las zonas corporales aquejadas de una disfunción,controlando la frecuencia o intensidad de estos campos.");
INSERT INTO keywords (name, description) VALUES ("MANIOBRA", "De mano y obra.Operación material que se ejecuta con las manos.-De masaje.Manera de realizar una manipulación de masaje sobre los tejidos.puede ser: roce,a masamiento,fricción,presión,percusión y vibración.");
INSERT INTO keywords (name, description) VALUES ("MASAJE", "Del fr.massage,de masser, amasar., In.,massage.Método manual o instrumental que consiste en rozar,amasar, presional, fricciónar, percutir o vibrar el cuerpo o una parte.-clásico. De él derivan las seis maniobras básicas (roce, amasamiento, fricción, presión, percusión y vibración) que dan lugar a las diferentes tecnicas de Masaje.Ver masoterapia.");
INSERT INTO keywords (name, description) VALUES ("MASOTERAPIA", "Tratamiento.Aplicación de las diferentes maniobras básicas de massaje con fines terapeuticos,dando lugar a las diferentes técnicas de masaje existentes.");
INSERT INTO keywords (name, description) VALUES ("MECANOTERAPIA", "De mecánica y el gr.therapeia, tratamiento. In., mecanotherapy.Tratamiento por medios mecanicos o por medio de aparatos que obligan al paciente a ejecutar pasiva o activamente movimientos determinados.");
INSERT INTO keywords (name, description) VALUES ("MÉTODO BAZ RAGAZ", "Método para la reeducación y fuerza muscular en el agua que se caracteriza por la utilización de anillos de flotación y que fue introducido por el Dr.Knufer en 1957 en la ciudad suiza de Bad Ragaz.");
INSERT INTO keywords (name, description) VALUES ("MINUSVALÍA", "Se trata de una situación desventajosa para un individuo determinado,consecuencia de una deficiencia o discapacidad, que limita o impide el desempeño de un rol que es normal en su caso.");
INSERT INTO keywords (name, description) VALUES ("MIOPATÍA", "Enfermedad primitiva de las fibras musculares, evoluciona empeorando progresivamente, periodos de empeoramiento se alternan con periodos de remisión. Se dividen en distrofias musculares y miotomías.");
INSERT INTO keywords (name, description) VALUES ("MOVIMIENTO", "De mover.In.,movement.Estado de un cuerpo que cambia de situación por efecto de una fuerza intrínseca o extrínseca que obra sobre él por un tiempo o continuamente;moción");
INSERT INTO keywords (name, description) VALUES ("MÚSCULO", "Del lat musculus. In., muscle. Nombre de los órganos carnosos productores de los movimientos en los organismos animales,compuestos de tejido fibroso y caracterizados principalmente por la contractilidad. El elemento anatómico constitutivo es la fibra muscular.");
INSERT INTO keywords (name, description) VALUES ("NERVIO", "De nervo,y éste del lat.nervus. In., nerve. Órgano en forma de cordón, conductor o transmisor de impulsos o sensaciones.");
INSERT INTO keywords (name, description) VALUES ("NEUROMA", "Tumores constituidos principalmente por células y fibras nerviosas que se desarrollan en un nervio.");
INSERT INTO keywords (name, description) VALUES ("ORTESIS", "Sistema de fuerzas diseñado para controlar,corregir o compensar una deformidad ósea ,las fuerzas deformantes o la ausencia de fuerza en el cuerpo.La ortesis suele requerir el uso de correctores especiales.");
INSERT INTO keywords (name, description) VALUES ("OSTEOPATÍA", "La osteopatía es el sistema de curación que pone el énfasis principal sobre la integridad estructural del cuerpo. Esta integridad estructural es el factor más importante a mantener.Rige la buena salud del organismo y evita la enfermedad.");
INSERT INTO keywords (name, description) VALUES ("OSTEOPOROSIS", "Disminución de masa ósea importante.Afecta de forma difusa al esqueleto y se caracteriza por una alteración de la microarquitectura del tejido óseo.Como consecuencia hay fragilidad ósea y riesgo aumetado de fractura.");
INSERT INTO keywords (name, description) VALUES ("PALPACIÓN", "Del lat,palpatio -onis.In.,palpation.Medio de exploración táctil diagnóstica que consiste en aplicar un contacto manual, con presión ligera o profunda, sobre una superficie para apreciar ciertas cualidades y el límite de los órganos subyacentes.");
INSERT INTO keywords (name, description) VALUES ("PARÁLISIS", "Es la disminución o ausencia patológica y mantenida del tono muscular debida a la lesión de una raíz nerviosa o de un nervio periférico.");
INSERT INTO keywords (name, description) VALUES ("PARAPLEJÍA", "Disminución o pérdida de la función motora y/o sensitiva en los segmentos torácicos,lumbares o sacros de la médula espinal (no cervicales), secundaria a una lesion de los elementos nerviosos dentro del canal neural.");
INSERT INTO keywords (name, description) VALUES ("PARKINSON enfermedad de", "(James Parkinson Médico Inglés).In,Parkinson´s Disease.Transtorno neurológico degenerativo,lentamente progresivo,caracterizado por temblor de reposo, movimientos de los dedos, facies de mascara, marcha torpe,flexión del tronco hacia delante con rigidez y debilidad muscular.");
INSERT INTO keywords (name, description) VALUES ("PASIVO", "Movimiento realizado sin la ayuda de una contracción muscular voluntaria por parte del sujeto.");
INSERT INTO keywords (name, description) VALUES ("PERFETTI,método de", "Este método se basa en la neuromotricidad y en la psicomotricidad. Perfetti, da importancia a la reeducación de la sensibilidad con repercusión en la reeducación motriz.");
INSERT INTO keywords (name, description) VALUES ("PLATO DE BOHELER", "Superficie circular intestable diseñada para trabajar la propiocepción al someter al paciente a una situación de desequilibrio postural.");
INSERT INTO keywords (name, description) VALUES ("PODAL", "Relativo o perteneciente a los pies.");
INSERT INTO keywords (name, description) VALUES ("POLITRAUMATISMO", "Lesionado con dos o mas lesiones traumáticas periféricas, viscerales o complejas que se asocian a un riesgo vital inmediato o secundario.");
INSERT INTO keywords (name, description) VALUES ("POSTURA", "Situación o modo en que está puesta una persona.Composición de las posiciones de todas las articulaciones del cuerpo en un momento dado.");
INSERT INTO keywords (name, description) VALUES ("PRESOTERAPIA", "Utilización de medios de contención hidráulicos con fines terapéuticos.Se emplea como método terapéutico combinado con drenaje linfático manual.Conjunto de técnicas de compresión continuas o intermitentes,que intentan reducir un edema.");
INSERT INTO keywords (name, description) VALUES ("PRONO", "Tumbado boca abajo;opuesto a supino");
INSERT INTO keywords (name, description) VALUES ("PROPIOCEPCIÓN", "In., propioception. Apreciación de la posicion equilibrio y sus cambios en el sistema muscular , especialmente en la locomoción.");
INSERT INTO keywords (name, description) VALUES ("PROTUSIÓN", "Grado de hernia discal donde el núcleo se luxa en sentido posterior , sin ruptura del anillo fibroso.");
INSERT INTO keywords (name, description) VALUES ("PSICOSOMÁTICO", "Perteeciente o relativo a la relación existente entre el la mente y el cuerpo, que tiene sintomas corporales de origen psíquico ,emocional o mental; tambien se llama psicofisiológico.");
INSERT INTO keywords (name, description) VALUES ("PUNTO GATILLO", "In., tigger points.Puntos cutáneos contracturados o dolorosos, hipersensibles a la presión.");
INSERT INTO keywords (name, description) VALUES ("QUISTE DE BAKER", "Herniación del tejido sinovial de la articulación de la rodilla por debilidad de la pared posterior de la cápsula.");
INSERT INTO keywords (name, description) VALUES ("REEDUCACIÓN", "In.,reeducatión.Método de tratamiento que consiste en enseñar a un paciente la práctica de actos o movimientos impedidos o dificultados por una lesión.");
INSERT INTO keywords (name, description) VALUES ("REFLEJO", "Del lat.reflexus .Que se produce involuntariamente como respuesta a un estímulo.");
INSERT INTO keywords (name, description) VALUES ("REFLEXOLOGIA", "In., reflexology. Estudio de los movimientos reflejos.");
INSERT INTO keywords (name, description) VALUES ("REFLEXOTERAPIA", "Del lat. reflexus, reflejo , y el gr.therapeia, tratamiento.Utilización terapéutica de ciertos reflejos.");
INSERT INTO keywords (name, description) VALUES ("SEDESTACIÓN", "Posición del paciente sentado sobre los isquiones y la columna erguida.");
INSERT INTO keywords (name, description) VALUES ("SHIATSU", "Del Jap. shi dedos.y atsu presión.Presión con el dedo. Método tradicional Japonés de digitopresión.");
INSERT INTO keywords (name, description) VALUES ("SÍNDROME DE DOLOR MIOFASCIAL", "Síntomas sensoriales,motores y autonómicos ocasionados por los puntos gatillos miofasciales.Debe de identificarse el músculo o grupo muscular responsable de los síntomas.");
INSERT INTO keywords (name, description) VALUES ("SINOVITIS", "Inflamación de la membrana sinovial articular debida a múltiples causas, como traumatismos, condromalacia,artritis,. que actúan estimulando a la sinovial a la producción de un exceso de líquido.");
INSERT INTO keywords (name, description) VALUES ("SOHIER,método de", "R. Sohier aplica su principio de la pinza que abre con una finalidad de liberación,y normaliza o vuelve a poner en su eje los apoyos interapofisarios. El fortalecimiento muscular pretende evitar la asimetria muscular y mantener la corrección.");
INSERT INTO keywords (name, description) VALUES ("STRETCHING", "Anglicismo que designa un concepto global de estiramientos.");
INSERT INTO keywords (name, description) VALUES ("SUPINACIÓN", "In.,Uno de los tipos de rotación que permiten determinadas articulaciones esquéticas,como las del codo o las de las muñecas, que permiten volver la palma de la mano hacia arriba.");
INSERT INTO keywords (name, description) VALUES ("SUPINO", "Opuesto a prono.Tumbado boca arriba.");
INSERT INTO keywords (name, description) VALUES ("TALASOTERAPIA", "Utilización con fines terapéuticos del medio marino. En estos tratamientos se suman los beneficios de la climatología marítima,la acción terapéutica del aire marino. Tambien se pueden utilizar algas, lodos , fangos, limos de los fondos marinos y las arenas.");
INSERT INTO keywords (name, description) VALUES ("TAPPING", "Anglicismo con el que se denomina el vendaje funcional.");
INSERT INTO keywords (name, description) VALUES ("TÉCNICA DE MICHELL", "O técnica de energia muscular,consiste en la realización a partir de un estiramiento musuclar, contracciones isométricas seguidas de un periodo de relajación. Al final de cada contracción se aumenta el estiramiento a la búsqueda de una nueva barrera motriz.");
INSERT INTO keywords (name, description) VALUES ("TENDINITIS", "Transtorno inflamatorio de un tendón. Sin.: tenonitis,tenosinitis.");
INSERT INTO keywords (name, description) VALUES ("TENDINOSIS", "Cuando la causa de la alteración del tendón es consecuencia del proceso degenerativo.");
INSERT INTO keywords (name, description) VALUES ("TERAPIA MANUAL ACUÁTICA", "Técnica hidrocinesiterápica que tiene la finalidad de retrasar la rigidez y pérdida de amplitud.");
INSERT INTO keywords (name, description) VALUES ("TERMOTERAPIA", "In., thermotherapy.Tratamiento de las enfermedades por las aplicaciones de calor en todas sus formas.");
INSERT INTO keywords (name, description) VALUES ("TETRAPLEJÍA", "Disminución o pérdida de la función motora y/o sensitiva en los segmentos cervicales de la médula por lesión de los elementos nerviosos dentro del canal espinal.Resulta de la pérdida o disminución de función en los brazos, en el tronco, en las piernas y en la zona pelvica.No incluye las lesiones del plexo braquial o de nervios periféricos fuera del canal neural.");
INSERT INTO keywords (name, description) VALUES ("TORTÍCOLIS", "Inclinación lateral o anterolateral , con discreta rotación de cabeza y cuello, asociada generalmente a contractuara o espasmo del músculo esternocleidomastoideo.");
INSERT INTO keywords (name, description) VALUES ("TRACCIÓN", "Acción de tirar,estirar o atraer.");
INSERT INTO keywords (name, description) VALUES ("TRAUMA O TRAUMATISMO", "Término general que comprende todas las lesiones internas o externas provocadas por una acción violenta.");
INSERT INTO keywords (name, description) VALUES ("TROMBOFEBITIS", "Aparición súbita de dolor punzante en una zona de eritema cutáneo con hinchazón local subcutáneo y dolor.");
INSERT INTO keywords (name, description) VALUES ("TROMOSIS", "Proceso de formación de un trombo en el interior de un vaso sanguíneo.");
INSERT INTO keywords (name, description) VALUES ("UMBAGO", "Dolor en las partes media e inferior de la columna ;termino descriptivo que no identifica un diagnóstico o causa.");
INSERT INTO keywords (name, description) VALUES ("VALGO", "Del lat valgus.,dirigido hacia fuera");
INSERT INTO keywords (name, description) VALUES ("VARICES", "Dilataciones , alargamientos y flexuosidades de las venas del sistema venoso superficial en los miembros inferiores, debidas a la pérdida de su elasticidad y a la atrofia o desaparición de sus válvulas.");
INSERT INTO keywords (name, description) VALUES ("VARO", "Del lat.varus.Dirigido hacia dentro.");
INSERT INTO keywords (name, description) VALUES ("VENDAJE", "In., bandage.Cura, apósito o estructura ligada o sostenida por vendas.");
INSERT INTO keywords (name, description) VALUES ("VENDAJE FUNCIONAL", "Es la contención dinámica que , utilizando vendas adhesivas extensibles o nextensibles oportunamente combinadas, se propone obtener la protección de determinadas estructuras musculo-tendinosas y cápsulo-ligamentosas frente a agentes patomecánicos., sin limitar totalmente la movilidad articular, sobre cualquier plano que ésta se desarrolle.");
INSERT INTO keywords (name, description) VALUES ("VOTJA, método de", "El método de desarrollo neuromotor según Votja está basado en el principio locomotor.En el dominio de la locomoción, existe cierta herencia filogenética desde el nacimiento.Los esquemas particulares de locomoción son la reptación refleja y la vuelta del cuerpo refleja (pasar del decúbito supino al decúbito prono).");
INSERT INTO keywords (name, description) VALUES ("WATSU", "Water Shiatsu, Aqua shiatsu,hydro shiatsu. Técnica hidrocinesiterápica que utiliza los estiramientos y movimientos del Zen Shiatsu en el medio acuático. Fue creado por Harold Dull en California en 1980.");
INSERT INTO keywords (name, description) VALUES ("ZONA NEUTRA", "Posición intermedia del recorrido articular entre la flexión y la extensión");